def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

N = 2021
factors = prime_factorization(N)
print(f"Prime factorization of {N}: {factors}")

def get_divisors(n, factors):
    divs = set()
    primes = list(factors.keys())

    def generate(index, current_divisor):
        if index == len(primes):
            divs.add(current_divisor)
            return

        p = primes[index]
        a = factors[p] + 1

        for i in range(a):
            generate(index + 1, current_divisor * (p**i))

    generate(0, 1)
    return sorted(list(divs))

divisors = get_divisors(N, factors)
print(f"Divisors of {N}: {divisors}")
